('#!/usr/bin/env bash\n# Purpose: Build/install the repo (editable) in one or more ASV micromamba envs, then run health checks.\nset -euo pipefail\n\n###### SETUP CODE (NOT TO BE MODIFIED) ######\n# Loads micromamba, common helpers, and persisted variables from the env stage.\nsource /etc/profile.d/asv_utils.sh || true\nsource /etc/profile.d/asv_build_vars.sh || true\n\nROOT_PATH=${ROOT_PATH:-$PWD}         # Usually /workspace/repo\nREPO_ROOT="$ROOT_PATH"\nTARGET_VERSIONS="${PY_VERSION:-${ASV_PY_VERSIONS:-}}"\nEXTRAS="${ALL_EXTRAS:+[$ALL_EXTRAS]}"\nif [[ -z "${TARGET_VERSIONS}" ]]; then\n  echo "Error: No PY_VERSION set and ASV_PY_VERSIONS not found." >&2\n  exit 1\nfi\n###### END SETUP CODE ######\n\n# -----------------------------\n# Build & test across envs\n# -----------------------------\nfor version in $TARGET_VERSIONS; do\n  ENV_NAME="asv_${version}"\n  log "==> Building in env: $ENV_NAME (python=$version)"\n\n  IMP="$(detect_import_name || true)"\n  log "Using import name: $IMP"\n\n  # Install core dependencies needed for building and testing\n  micromamba install -y -n "$ENV_NAME" -c conda-forge \\\n    pip setuptools wheel git conda mamba "libmambapy<=1.9.9" \\\n    numpy scipy pandas matplotlib \\\n    sqlalchemy>=1.4.2 alembic>=1.5.0 colorlog tqdm pyyaml \\\n    pytest coverage "fakeredis[lua]" \\\n    scikit-learn>=0.24.2 grpcio "protobuf>=5.28.1"\n\n  # Install PyTorch for Python versions <= 3.12 as specified in pyproject.toml\n  if [[ "${version}" =~ ^3.(8|9|10|11|12)$ ]]; then\n    micromamba install -y -n "$ENV_NAME" -c pytorch -c conda-forge pytorch cpuonly\n  fi\n\n  # Editable install with test extras\n  log "Editable install with test extras"\n  if ! micromamba run -n "$ENV_NAME" pip install -e "$REPO_ROOT[test]"; then\n    warn "Failed to install with test extras, trying base install"\n    micromamba run -n "$ENV_NAME" pip install -e "$REPO_ROOT"\n  fi\n\n  # Health checks\n  log "Running smoke checks"\n  micromamba run -n "$ENV_NAME" asv_smokecheck.py --import-name "$IMP" --repo-root "$REPO_ROOT" ${RUN_PYTEST_SMOKE:+--pytest-smoke}\n\n  echo "::import_name=${IMP}::env=${ENV_NAME}"\ndone\n\nlog "All builds complete ✅"', '\n\n# Step [1/5]\n# Action: list_tree\n# Input: {"depth": 2}\n# Observation:\n{\n  "repo_root": "/workspace/repo",\n  "files": [\n    ".git/config",\n    ".git/info/exclude",\n    ".git/description",\n    ".git/hooks/prepare-commit-msg.sample",\n    ".git/hooks/update.sample",\n    ".git/hooks/applypatch-msg.sample",\n    ".git/hooks/push-to-checkout.sample",\n    ".git/hooks/post-update.sample",\n    ".git/hooks/fsmonitor-watchman.sample",\n    ".git/hooks/pre-rebase.sample",\n    ".git/hooks/pre-receive.sample",\n    ".git/hooks/pre-merge-commit.sample",\n    ".git/hooks/pre-applypatch.sample",\n    ".git/hooks/pre-commit.sample",\n    ".git/hooks/commit-msg.sample",\n    ".git/hooks/sendemail-validate.sample",\n    ".git/hooks/pre-push.sample",\n    ".git/HEAD",\n    ".git/packed-refs",\n    ".git/index",\n    ".git/logs/HEAD",\n    "setup.cfg",\n    "MANIFEST.in",\n    "optuna/storages/_in_memory.py",\n    "optuna/storages/_cached_storage.py",\n    "optuna/storages/_heartbeat.py",\n    "optuna/storages/__init__.py",\n    "optuna/storages/_base.py",\n    "optuna/storages/_callbacks.py",\n    "optuna/trial/_trial.py",\n    "optuna/trial/_frozen.py",\n    "optuna/trial/_fixed.py",\n    "optuna/trial/_state.py",\n    "optuna/trial/__init__.py",\n    "optuna/trial/_base.py",\n    "optuna/cli.py",\n    "optuna/_imports.py",\n    "optuna/importance/_mean_decrease_impurity.py",\n    "optuna/importance/__init__.py",\n    "optuna/importance/_base.py",\n    "optuna/terminator/erroreval.py",\n    "optuna/terminator/terminator.py",\n    "optuna/terminator/callback.py",\n    "optuna/terminator/median_erroreval.py",\n    "optuna/terminator/__init__.py",\n    "optuna/logging.py",\n    "optuna/visualization/_plotly_imports.py",\n    "optuna/visualization/_edf.py",\n    "optuna/visualization/_parallel_coordinate.py",\n    "optuna/visualization/_contour.py",\n    "optuna/visualization/_pareto_front.py",\n    "optuna/visualization/_utils.py",\n    "optuna/visualization/_intermediate_values.py",\n    "optuna/visualization/_slice.py",\n    "optuna/visualization/_terminator_improvement.py",\n    "optuna/visualization/_param_importances.py",\n    "optuna/visualization/_timeline.py",\n    "optuna/visualization/_rank.py",\n    "optuna/visualization/_hypervolume_history.py",\n    "optuna/visualization/__init__.py",\n    "optuna/visualization/_optimization_history.py",\n    "optuna/samplers/_random.py",\n    "optuna/samplers/_cmaes.py",\n    "optuna/samplers/_brute_force.py",\n    "optuna/samplers/_grid.py",\n    "optuna/samplers/_lazy_random_state.py",\n    "optuna/samplers/_qmc.py",\n    "optuna/samplers/_partial_fixed.py",\n    "optuna/samplers/__init__.py",\n    "optuna/samplers/_base.py",\n    "optuna/pruners/_successive_halving.py",\n    "optuna/pruners/_nop.py",\n    "optuna/pruners/_patient.py",\n    "optuna/pruners/_hyperband.py",\n    "optuna/pruners/_median.py",\n    "optuna/pruners/_wilcoxon.py",\n    "optuna/pruners/_threshold.py",\n    "optuna/pruners/_percentile.py",\n    "optuna/pruners/__init__.py",\n    "optuna/pruners/_base.py",\n    "optuna/_typing.py",\n    "optuna/testing/objectives.py",\n    "optuna/testing/visualization.py",\n    "optuna/testing/pruners.py",\n    "optuna/testing/storages.py",\n    "optuna/testing/tempfile_pool.py",\n    "optuna/testing/samplers.py",\n    "optuna/testing/threading.py",\n    "optuna/testing/trials.py",\n    "optuna/testing/__init__.py",\n    "optuna/_gp/search_space.py",\n    "optuna/_gp/optim_mixed.py",\n    "optuna/_gp/acqf.py",\n    "optuna/_gp/gp.py",\n    "optuna/_gp/prior.py",\n    "optuna/_gp/__init__.py",\n    "optuna/_gp/optim_sample.py",\n    "optuna/version.py",\n    "optuna/study/_study_summary.py",\n    "optuna/study/study.py",\n    "optuna/study/_study_direction.py",\n    "optuna/study/_tell.py",\n    "optuna/study/_frozen.py",\n    "optuna/study/_constrained_optimization.py",\n    "optuna/study/_dataframe.py",\n    "optuna/study/_multi_objective.py",\n    "optuna/study/_optimize.py",\n    "optuna/study/__init__.py",\n    "optuna/artifacts/_download.py",\n    "optuna/artifacts/_protocol.py",\n    "optuna/artifacts/_backoff.py",\n    "optuna/artifacts/_boto3.py",\n    "op\n\n# Step [2/5]\n# Action: read_file\n# Input: {"path": "pyproject.toml", "max_bytes": 65536}\n# Observation:\n--- BEGIN /workspace/repo/pyproject.toml ---\n[build-system]\nrequires = ["setuptools >= 61.1.0", "wheel"]\nbuild-backend = "setuptools.build_meta"\n\n[project]\nname = "optuna"\ndescription = "A hyperparameter optimization framework"\nreadme = "README.md"\nauthors = [\n  {name = "Takuya Akiba"}\n]\nclassifiers = [\n  "Development Status :: 5 - Production/Stable",\n  "Intended Audience :: Science/Research",\n  "Intended Audience :: Developers",\n  "License :: OSI Approved :: MIT License",\n  "Programming Language :: Python :: 3",\n  "Programming Language :: Python :: 3.8",\n  "Programming Language :: Python :: 3.9",\n  "Programming Language :: Python :: 3.10",\n  "Programming Language :: Python :: 3.11",\n  "Programming Language :: Python :: 3.12",\n  "Programming Language :: Python :: 3.13",\n  "Programming Language :: Python :: 3 :: Only",\n  "Topic :: Scientific/Engineering",\n  "Topic :: Scientific/Engineering :: Mathematics",\n  "Topic :: Scientific/Engineering :: Artificial Intelligence",\n  "Topic :: Software Development",\n  "Topic :: Software Development :: Libraries",\n  "Topic :: Software Development :: Libraries :: Python Modules",\n]\nrequires-python = ">=3.8"\ndependencies = [\n  "alembic>=1.5.0",\n  "colorlog",\n  "numpy",\n  "packaging>=20.0",\n  "sqlalchemy>=1.4.2",\n  "tqdm",\n  "PyYAML",  # Only used in `optuna/cli.py`.\n]\ndynamic = ["version"]\n\n[project.optional-dependencies]\nbenchmark = [\n  "asv>=0.5.0",\n  "cma",\n  "virtualenv"\n]\nchecking = [\n  "black",\n  "blackdoc",\n  "flake8",\n  "isort",\n  "mypy",\n  "mypy_boto3_s3",\n  "types-PyYAML",\n  "types-redis",\n  "types-setuptools",\n  "types-tqdm",\n  "typing_extensions>=3.10.0.0",\n]\ndocument = [\n  "ase",\n  "cmaes>=0.10.0",  # optuna/samplers/_cmaes.py.\n  "fvcore",\n  "kaleido<0.4",  # TODO(nzw0301): Remove the version constraint by installing browser separately.\n  "lightgbm",\n  "matplotlib!=3.6.0",\n  "pandas",\n  "pillow",\n  "plotly>=4.9.0",  # optuna/visualization.\n  "scikit-learn",\n  "sphinx",\n  "sphinx-copybutton",\n  "sphinx-gallery",\n  "sphinx-notfound-page",\n  "sphinx_rtd_theme>=1.2.0",\n  "torch",\n  "torchvision",\n]\noptional = [\n  "boto3",  # optuna/artifacts/_boto3.py.\n  "cmaes>=0.10.0",  # optuna/samplers/_cmaes.py.\n  "google-cloud-storage",  # optuna/artifacts/_gcs.py.\n  "matplotlib!=3.6.0",  # optuna/visualization/matplotlib.\n  "pandas",  # optuna/study/_dataframe.py.\n  "plotly>=4.9.0",  # optuna/visualization.\n  "redis",  # optuna/storages/journal/_redis.py.\n  "scikit-learn>=0.24.2",  # optuna/importance.\n  "scipy",  # optuna/_gp.\n  "torch; python_version<=\'3.12\'",  # TODO(gen740): Remove this line when \'torch\', a dependency of \'optuna/_gp\', supports Python 3.13\n  "grpcio",  # optuna/storages/_grpc.\n  "protobuf>=5.28.1",  # optuna/storages/_grpc.\n]\ntest = [\n  "coverage",\n  "fakeredis[lua]",\n  "kaleido<0.4",  # TODO(nzw0301): Remove the version constraint by installing browser separately.\n  "moto",\n  "pytest",\n  "scipy>=1.9.2",\n  "torch; python_version<=\'3.12\'",  # TODO(gen740): Remove this line when \'torch\', a dependency of \'optuna/_gp\', supports Python 3.13\n  "grpcio",  # optuna/storages/_grpc.\n  "protobuf>=5.28.1",  # optuna/storages/_grpc.\n]\n\n[project.urls]\nhomepage = "https://optuna.org/"\nrepository = "https://github.com/optuna/optuna"\ndocumentation = "https://optuna.readthedocs.io"\nbugtracker = "https://github.com/optuna/optuna/issues"\n\n[project.scripts]\noptuna = "optuna.cli:main"\n\n[tool.setuptools.packages.find]\ninclude = ["optuna*"]\n\n[tool.setuptools.dynamic]\nversion = {attr = "optuna.version.__version__"}\n\n[tool.setuptools.package-data]\n"optuna" = [\n  "storages/_rdb/alembic.ini",\n  "storages/_rdb/alembic/*.*",\n  "storages/_rdb/alembic/versions/*.*",\n  "py.typed",\n]\n\n[tool.black]\nline-length = 99\ntarget-version = [\'py38\']\nforce-exclude = \'\'\'\n/(\n  \\.eggs\n  | \\.git\n  | \\.hg\n  | \\.mypy_cache\n  | \\.venv\n  | venv\n  | _build\n  | buck-out\n  | build\n  | dist\n  | docs\n  | optuna/storages/_grpc/auto_generated\n)/\n\'\'\'\n\n[tool.isort]\nprofile = \'black\'\nsrc_paths = [\'optuna\', \'tests\', \'docs\', \'benchmarks\']')
